// Env (DB, FILES_KV, ADMIN_EMAILS) is generated by `wrangler types`
// in worker-configuration.d.ts. This augments it with optional bindings.
interface Env {
  FILES?: R2Bucket;
  ASSETS?: Fetcher;
}

interface UserRow {
  id: string;
  email: string;
  username: string;
  display_name: string;
  password_hash: string;
  role: 'user' | 'admin';
  created_at: number;
}

interface ModelRow {
  id: string;
  slug: string;
  user_id: string;
  title: string;
  description: string;
  category_slug: string;
  tags: string;
  license: string;
  print_settings: string;
  status: 'draft' | 'pending' | 'approved' | 'rejected';
  reject_reason: string | null;
  cover_file_id: string | null;
  likes_count: number;
  downloads_count: number;
  created_at: number;
  updated_at: number;
  published_at: number | null;
}

interface ModelFileRow {
  id: string;
  model_id: string;
  kind: 'model' | 'image';
  filename: string;
  storage_key: string;
  size: number;
  content_type: string;
  sort: number;
  created_at: number;
}

interface AuthUser {
  id: string;
  email: string;
  username: string;
  display_name: string;
  role: 'user' | 'admin';
}
